-- READ-ONLY aggregate of observed raw RH conflicts; no source truth inference.
WITH gaps AS (SELECT '2019:1572134100:1572138000' gap_id, 1572134100 left_time, 1572138000 right_time UNION ALL SELECT '2020:1582604400:1582613100' gap_id, 1582604400 left_time, 1582613100 right_time UNION ALL SELECT '2020:1582666200:1582680000' gap_id, 1582666200 left_time, 1582680000 right_time UNION ALL SELECT '2020:1583030400:1583038800' gap_id, 1583030400 left_time, 1583038800 right_time UNION ALL SELECT '2020:1583044200:1583069100' gap_id, 1583044200 left_time, 1583069100 right_time UNION ALL SELECT '2020:1583069100:1583089800' gap_id, 1583069100 left_time, 1583089800 right_time UNION ALL SELECT '2020:1583110200:1583117400' gap_id, 1583110200 left_time, 1583117400 right_time UNION ALL SELECT '2020:1583125800:1583140800' gap_id, 1583125800 left_time, 1583140800 right_time UNION ALL SELECT '2020:1589369100:1589372700' gap_id, 1589369100 left_time, 1589372700 right_time UNION ALL SELECT '2020:1589378700:1589384400' gap_id, 1589378700 left_time, 1589384400 right_time UNION ALL SELECT '2020:1589387400:1589402100' gap_id, 1589387400 left_time, 1589402100 right_time UNION ALL SELECT '2020:1592803800:1592827800' gap_id, 1592803800 left_time, 1592827800 right_time UNION ALL SELECT '2020:1592890500:1592915400' gap_id, 1592890500 left_time, 1592915400 right_time)
SELECT g.gap_id, ROUND(w.outHumidity-o.outHumidity,1) raw_delta_wh_minus_old, COUNT(*) pair_count, MIN(o.outHumidity) old_min, MAX(o.outHumidity) old_max, MIN(w.outHumidity) wh_min, MAX(w.outHumidity) wh_max
FROM gaps g JOIN `old_weewx`.archive o ON o.dateTime>g.left_time AND o.dateTime<g.right_time JOIN `weewx_WH1080`.archive w ON w.dateTime=o.dateTime
WHERE o.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL AND o.outHumidity<>w.outHumidity
GROUP BY g.gap_id, ROUND(w.outHumidity-o.outHumidity,1) ORDER BY g.gap_id, pair_count DESC;
